/// <reference lib="webworker" />
/**
 * Offline support.
 *
 * - The app's own files are cached as ONE versioned snapshot (all-or-nothing), served cache-first,
 *   so a phone never mixes files from two versions. A new version is downloaded in the background
 *   and used from the next launch.
 * - trip.enc is data: network-first (3 s), so trip updates show on the same launch.
 * - Google Fonts: cache-first, in their own cache so code updates don't drop them.
 * - The weather API is not touched: the app keeps its own copy.
 *
 * The block between the markers is generated by `trip precache` (run it after changing any file in web/).
 */

// prettier-ignore
// <precache> generated by `trip precache`: do not edit by hand
const VERSION = '02f5f96b0d65';
const APP_FILES = [
  './',
  'css/app.css',
  'css/tokens.css',
  'icon-192.png',
  'icon-512.png',
  'icon.svg',
  'index.html',
  'js/actions.js',
  'js/app.js',
  'js/html.js',
  'js/i18n.js',
  'js/main.js',
  'js/state.js',
  'js/trip.js',
  'js/ui/components.js',
  'js/ui/screens.js',
  'js/ui/sheets.js',
  'js/util.js',
  'js/vault.js',
  'js/weather.js',
  'locales/en/app.json',
  'locales/ru/app.json',
  'manifest.webmanifest',
];
// </precache>

const sw = /** @type {ServiceWorkerGlobalScope} */ (/** @type {unknown} */ (self));

const APP_CACHE = `our-trip-app-${VERSION}`;
const DATA_CACHE = 'our-trip-data';
const FONT_CACHE = 'our-trip-fonts';
const OURS = [APP_CACHE, DATA_CACHE, FONT_CACHE];

sw.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const app = await caches.open(APP_CACHE);
      await app.addAll(APP_FILES.map((url) => new Request(url, { cache: 'reload' })));
      // best effort: the trip itself, so the very first offline launch has it
      const data = await caches.open(DATA_CACHE);
      await data.add(new Request('trip.enc', { cache: 'reload' })).catch(() => {});
      await sw.skipWaiting();
    })(),
  );
});

sw.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      // only our own old caches: other sites on the same github.io origin keep theirs
      const names = await caches.keys();
      await Promise.all(
        names.filter((n) => n.startsWith('our-trip-') && !OURS.includes(n)).map((n) => caches.delete(n)),
      );
      await sw.clients.claim();
    })(),
  );
});

/**
 * Try the network for 3 seconds, otherwise the saved copy.
 * @param {Request} request
 * @param {string} cacheName
 */
async function networkFirst(request, cacheName) {
  const cache = await caches.open(cacheName);
  try {
    const response = await Promise.race([
      fetch(request),
      new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), 3000)),
    ]);
    if (response.ok) await cache.put(request, response.clone());
    return response;
  } catch {
    return (await cache.match(request, { ignoreSearch: true })) ?? Response.error();
  }
}

/**
 * The saved copy, otherwise the network (and save it).
 * @param {Request} request
 * @param {string} cacheName
 */
async function cacheFirst(request, cacheName) {
  const cache = await caches.open(cacheName);
  const hit = await cache.match(request, { ignoreSearch: true });
  if (hit) return hit;
  const response = await fetch(request);
  if (response.ok || response.type === 'opaque') await cache.put(request, response.clone());
  return response;
}

/**
 * An app file from the snapshot; pages fall back to index.html.
 * @param {Request} request
 */
async function appFile(request) {
  const cache = await caches.open(APP_CACHE);
  const hit =
    (await cache.match(request, { ignoreSearch: true })) ??
    (request.mode === 'navigate' ? await cache.match('index.html') : undefined);
  return hit ?? fetch(request);
}

sw.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.hostname === 'fonts.googleapis.com' || url.hostname === 'fonts.gstatic.com') {
    event.respondWith(cacheFirst(request, FONT_CACHE));
  } else if (url.origin !== sw.location.origin) {
    // weather API and other sites: always live
  } else if (url.pathname.endsWith('/trip.enc')) {
    event.respondWith(networkFirst(request, DATA_CACHE));
  } else {
    event.respondWith(appFile(request));
  }
});
